window.AUTH=window.AUTH||{};window.AUTH["17-1026"]={"d":"17-1026","id":"2018/17-1026","n":"Garza v. Idaho","briefs":[{"k":"petitioner","label":"Brief of petitioner Gilberto Garza, Jr.","date":"2018-08-10","url":"https://www.supremecourt.gov/DocketPDF/17/17-1026/59116/20180810121524251_17-1026ts.pdf","side":"pet","n":102},{"k":"respondent","label":"Brief of respondent State of Idaho","date":"2018-09-17","url":"https://www.supremecourt.gov/DocketPDF/17/17-1026/63869/20180917103707513_36609%20pdf%20Deck.pdf","side":"res","n":34},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2018-09-24","url":"https://www.supremecourt.gov/DocketPDF/17/17-1026/64674/20180924160305812_17-1026bsacUnitedStates.pdf","side":"us","n":67},{"k":"reply","label":"Reply of petitioner Gilberto Garza, Jr.","date":"2018-10-17","url":"https://www.supremecourt.gov/DocketPDF/17/17-1026/67196/20181017145116679_17-1026rbA.PDF","side":"pet","n":23}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-1026_2c83.pdf","tr":true,"items":[{"t":"case","label":"Anders v. California","cite":"386 U.S. 738","y":1967,"id":"1966/98","sc":1,"op":2,"ar":19,"sum":"The failure to grant this indigent petitioner seeking initial review of his conviction the services of an advocate, as contrasted with an amicus curiae, which would have been available to an appellant with financial means, violated petitioner's rights to fair procedure and equality under the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27, 28, 39","1":"36","2":"26","3":"2, 5"}},{"t":"case","label":"Ballweber v. State","cite":"457 N.W.2d 215","y":1990,"court":"Minn. Ct. App.","url":"https://www.courtlistener.com/c/N.W.2d/457/215/","by":{"0":"34"}},{"t":"case","label":"Bookwalter v. United States","cite":"2018 WL 2407525","y":2018,"court":"E.D. Tenn. May 25","by":{"0":"40"}},{"t":"case","label":"Brookhart v. Janis","cite":"384 U.S. 1","y":1966,"id":"1965/657","sc":1,"sum":"Petitioner's constitutional right to plead not guilty and to have a trial where he could confront and cross-examine adversary witnesses could not be\"waived by his counsel without petitioner's consent. Pp. 5-8. 2 Ohio St. 2d 36, 205 N. E. 2d 911, reversed and remanded.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Campusano v. United States","cite":"442 F.3d 770","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/442/770/","op":1,"by":{"0":"18, 19","2":"28"}},{"t":"case","label":"Ceasar v. United States","cite":"2018 WL 1964197","y":2018,"court":"M.D. Fla. Apr. 26","by":{"0":"40"}},{"t":"case","label":"Class v. United States","cite":"138 S. Ct. 798","y":2018,"id":"2017/16-424","sc":1,"sum":"The Court held that a guilty plea alone does not waive a defendant’s right to challenge the constitutionality of his conviction on direct appeal.","sumSrc":"Oyez","by":{"0":"21","2":"20","3":"8, 9"}},{"t":"case","label":"Coleman v. Thompson","cite":"501 U.S. 722","y":1991,"id":"1990/89-7662","sc":1,"sum":"Coleman's claims presented for the first time in the state habeas proceeding are not subject to review in federal habeas.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"29, 38","1":"35","2":"24"}},{"t":"case","label":"Devine v. United States","cite":"520 F.3d 1286","y":2008,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/520/1286/","by":{"0":"41"}},{"t":"case","label":"Evitts v. Lucey","cite":"469 U.S. 387","y":1985,"id":"1984/83-1378","sc":1,"sum":"The Due Process Clause of the Fourteenth Amendment guarantees a criminal defendant the effective assistance of counsel on his first appeal as of right.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10","2":"19","3":"2, 17"}},{"t":"case","label":"Faretta v. California","cite":"422 U.S. 806","y":1975,"id":"1974/73-5772","sc":1,"sum":"The Supreme Court held that a defendant in a state criminal trial has the constitutional right to defend himself when he voluntarily and intelligently wants to do so. In this case, Faretta was deprived of that constitutional right. Farretta’s knowledge of the hearsay rule and court procedure was irrelevant to whether he voluntarily waived his right to counsel.","sumSrc":"Oyez","by":{"0":"26","3":"10"}},{"t":"case","label":"Ferrier v. State","cite":"25 P.3d 110","y":2001,"court":"Idaho","url":"https://www.courtlistener.com/c/P.3d/25/110/","by":{"0":"3","3":"23"}},{"t":"case","label":"Florida v. Nixon","cite":"543 U.S. 175","y":2004,"id":"2004/03-931","sc":1,"sum":"In a unanimous 8-0 decision, the Court ruled that Nixon's lawyer's strategy - pursued without Nixon's express approval - did not automatically qualify the lawyer as ineffective. The Court reversed the ruling of the Florida Supreme Court, faulting that court for inappropriately applying presumptions of prejudice and deficient performance.","sumSrc":"Oyez","by":{"0":"24","1":"19, 22, 31, 33","2":"12"}},{"t":"case","label":"Gonzalez v. United States","cite":"553 U.S. 242","y":2008,"id":"2007/06-11612","sc":1,"sum":"The Court held 8-1 that express consent by counsel suffices to permit a magistrate judge to preside over jury selection in a felony trial, stating that such \"scheduling matters\" are among those for which agreement by counsel generally controls. Seven Justices formed the majority opinion written by Justice Anthony Kennedy with Justice Antonin Scalia concurring in the judgment and Justice Clarence Thomas dissenting.","sumSrc":"Oyez","by":{"0":"23, 24"}},{"t":"case","label":"Gonzalez v. United States","cite":"2012 WL 5471799","y":2012,"court":"D. Mass. Nov. 8","by":{"0":"40"}},{"t":"case","label":"Gonzalez v. United States","cite":"2015 WL 5797628","y":2015,"court":"E.D.N.C. Oct. 1","by":{"0":"40"}},{"t":"case","label":"Haines v. Kerner","cite":"404 U.S. 519","y":1972,"id":"1971/70-5025","sc":1,"sum":"The Court held that a prisoner has the right to submit proof of his alleged injuries before his case is dismissed.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Jackson v. Attorney Gen. of Nevada","cite":"268 F. App’x 615","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/268/615/","sum":"Finding “no merit” to petitioner’s argument “[u]nder the first prong of the Flores-Ortega test” in part because the petitioner “waived all appellate rights” except challenges to jurisdiction or legality.","sumSrc":"brief:0","by":{"0":"41"}},{"t":"case","label":"Johnson v. United States","cite":"2018 WL 1734920","y":2018,"court":"E.D.N.C. Mar. 14","by":{"0":"41"}},{"t":"case","label":"Jones v. Barnes","cite":"463 U.S. 745","y":1983,"id":"1982/81-1794","sc":1,"op":4,"ar":1,"sum":"Defense counsel assigned to prosecute an appeal from a criminal conviction does not have a constitutional duty to raise every nonfrivolous issue requested by the defendant. The accused has the ultimate authority to make certain fundamental decisions regarding his case, including the decision whether to take an appeal; and, with some limitations, he may elect to act as his own advocate. However, an indigent defendant …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 23, 24","1":"19","2":"15","3":"passim"}},{"t":"case","label":"Lafler v. Cooper","cite":"566 U.S. 156","y":2012,"id":"2011/10-209","sc":1,"sum":"The Court found that the test to determine ineffective assistance of counsel, from Strickland v. Washington, was not properly applied in an aggravated assault case.","sumSrc":"Oyez","by":{"0":"10"}},{"t":"case","label":"Lee v. United States","cite":"137 S. Ct. 1958","y":2017,"id":"2016/16-327","sc":1,"sum":"The Court determined that, when a defendant claims that his plea was caused by ineffective assistance of counsel, the defendant can demonstrate that he was prejudiced by showing a reasonable probability that, but for his counsel’s errors, he would have gone to trial rather than accepting a plea.","sumSrc":"Oyez","by":{"0":"passim","1":"12","2":"11, 16","3":"8"}},{"t":"case","label":"Mays v. United States","cite":"2018 WL 3301895","y":2018,"court":"M.D. Fla. July 5","by":{"0":"42"}},{"t":"case","label":"McCoy v. Louisiana","cite":"138 S. Ct. 1500","y":2018,"id":"2017/16-8255","sc":1,"op":4,"sum":"The Court held that a criminal defendant has the right under the Sixth Amendment to insist that his attorney not concede guilt in a capital case.","sumSrc":"Oyez","by":{"0":"passim","1":"20","2":"25","3":"passim"}},{"t":"case","label":"Moya v. United States","cite":"2018 WL 3039340","y":2018,"court":"N.D. Tex. May 30","by":{"0":"42"}},{"t":"case","label":"Nunez v. United States","cite":"546 F.3d 450","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/546/450/","op":2,"by":{"0":"25","1":"14, 19","2":"6, 26, 29, 30"}},{"t":"case","label":"Pabon v. Wright","cite":"459 F.3d 241","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/459/241/","by":{"0":"37"}},{"t":"case","label":"Parsons v. United States","cite":"505 F.3d 797","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/505/797/","sum":"Finding that petitioner failed to establish duty to consult under Flores-Ortega in part because he “had waived his right to appeal”.","sumSrc":"brief:0","by":{"0":"41"}},{"t":"case","label":"Peguero v. United States","cite":"526 U.S. 23","y":1999,"id":"1998/97-9217","sc":1,"op":1,"sum":"The Court held that \"a district court's failure to advise the defendant of his right to appeal does not entitle him to habeas relief if he knew of his right and hence suffered no prejudice from the omission.\" Noting the importance of the rule and acknowledging that the omission was an error, Justice Kennedy stated \"[t]rial judges must be meticulous and precise in following each of the requirements of Rule 32 in every case.\" The Court concluded that Rule 32 violations do not entitle defendants to relief in all circumstances, rather only when the defendant is prejudiced by the court's error.","sumSrc":"Oyez","by":{"0":"12, 15, 24, 30","1":"14, 15"}},{"t":"case","label":"Penson v. Ohio","cite":"488 U.S. 75","y":1988,"id":"1988/87-6116","sc":1,"op":2,"sum":"After the indigent petitioner and two codefendants were found guilty of several serious crimes in an Ohio state court, the new counsel appointed to represent petitioner on appeal filed with the Ohio Court of Appeals a document captioned \"Certification of Meritless Appeal and Motion,\" which recited that the attorney had carefully reviewed the record, that he had found no errors requiring reversal, and that he would …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"10, 27, 28, 39","3":"5, 6"}},{"t":"case","label":"Perez v. United States","cite":"2016 WL 4276006","y":2016,"court":"N.D. Tex. May 31","by":{"0":"42"}},{"t":"case","label":"Rodriquez v. United States","cite":"395 U.S. 327","y":1969,"id":"1968/749","sc":1,"op":3,"sum":"Petitioner, allegedly of Mexican descent with a limited knowledge of English, was convicted on several narcotics charges. Immediately after petitioner was sentenced in June 1963, his retained counsel indicated orally that petitioner wished to appeal in for a pauperis. The trial judge, who did not advise petitioner of his right of appeal, told petitioner s counsel that all motions had to be in writing and adjourned …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"14, 15"}},{"t":"case","label":"Roe v. Flores-Ortega","cite":"528 U.S. 470","y":2000,"id":"1999/98-1441","sc":1,"op":27,"ar":14,"sum":"The Court held that counsel is not always required to file a notice of appeal after their clients plead guilty unless the clients specifically ask them to so. \"We cannot say, as a constitutional matter, that in every case counsel's failure to consult with the defendant about an appeal is necessarily unreasonable and therefore deficient,\" Justice O'Connor wrote for the majority. \"We therefore reject a bright-line rule that counsel must always consult with the defendant regarding an appeal,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"Smith v. Robbins","cite":"528 U.S. 259","y":2000,"id":"1999/98-1037","sc":1,"op":14,"sum":"The Court held that \"States are free to adopt different procedures, so long as those procedures adequately safeguard a defendant's right to appellate counsel,\" as does California's procedure.","sumSrc":"Oyez","by":{"0":"27","1":"22, 31, 32, 36","2":"26","3":"5"}},{"t":"case","label":"Spear v. United States","cite":"2015 WL 9583525","y":2015,"court":"N.D. Tex. Nov. 18","sum":"Finding “no reason, given Petitioner’s limited appeal rights, for counsel to believe that a rational defendant would want to appeal”.","sumSrc":"brief:0","by":{"0":"42"}},{"t":"case","label":"State v. Allen","cite":"141 P.3d 1136","y":2006,"court":"Idaho Ct. App.","url":"https://www.courtlistener.com/c/P.3d/141/1136/","by":{"0":"17"}},{"t":"case","label":"State v. Cope","cite":"2005 WL 783356","y":2005,"court":"Idaho Ct. App. Apr. 8","by":{"0":"17"}},{"t":"case","label":"State v. Cope","cite":"129 P.3d 1241","y":2006,"court":"Idaho","url":"https://www.courtlistener.com/c/P.3d/129/1241/","by":{"0":"4, 17","2":"15"}},{"t":"case","label":"State v. Eger","cite":"155 P.3d 784","y":2007,"court":"N.M. Ct. App.","url":"https://www.courtlistener.com/c/P.3d/155/784/","by":{"0":"34"}},{"t":"case","label":"State v. Holdaway","cite":"943 P.2d 72","y":1997,"court":"Idaho Ct. App.","url":"https://www.courtlistener.com/c/P.2d/943/72/","by":{"0":"17"}},{"t":"case","label":"State v. Kelchner","cite":"936 P.2d 680","y":1997,"court":"Idaho","url":"https://www.courtlistener.com/c/P.2d/936/680/","sum":"Explaining that the act of pleading guilty “constitutes a waiver of all non-jurisdictional defects”.","sumSrc":"brief:0","by":{"0":"21"}},{"t":"case","label":"State v. Loye","cite":"670 N.W.2d 141","y":2003,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W.2d/670/141/","by":{"0":"34"}},{"t":"case","label":"State v. McKenney","cite":"568 P.2d 1213","y":1977,"court":"Idaho","url":"https://www.courtlistener.com/c/P.2d/568/1213/","by":{"0":"27, 39"}},{"t":"case","label":"State v. Murphy","cite":"872 P.2d 719","y":1994,"court":"Idaho","url":"https://www.courtlistener.com/c/P.2d/872/719/","by":{"0":"4, 17","1":"35"}},{"t":"case","label":"State v. Rodriguez","cite":"2018 WL 700168","y":2018,"court":"Idaho Ct. App. Feb. 5","by":{"0":"17"}},{"t":"case","label":"State v. Sainz","cite":"526 A.2d 1015","y":1987,"court":"N.J.","url":"https://www.courtlistener.com/c/A.2d/526/1015/","by":{"0":"34"}},{"t":"case","label":"State v. Straub","cite":"292 P.3d 273","y":2013,"court":"Idaho","url":"https://www.courtlistener.com/c/P.3d/292/273/","by":{"0":"17, 35"}},{"t":"case","label":"State v. Taylor","cite":"336 P.3d 302","y":2014,"court":"Idaho Ct. App.","url":"https://www.courtlistener.com/c/P.3d/336/302/","sum":"Rejecting the assertion that the applicability of an appeal waiver must be assessed through a pre-briefing motion to dismiss.","sumSrc":"brief:3","by":{"0":"17","3":"7"}},{"t":"case","label":"Stolkner v. United States","cite":"2018 WL 3212007","y":2018,"court":"D. Me. June 29","by":{"0":"40"}},{"t":"case","label":"Strickland v. Washington","cite":"466 U.S. 668","y":1984,"id":"1983/82-1554","sc":1,"op":12,"ar":5,"sum":"The Supreme Court held that: (1) counsel's performance must be deficient; and (2) the deficient performance must have prejudiced the defense so as to deprive the defendant of a fair trial.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"4, 7, 10, 12, 19, 23"}},{"t":"case","label":"United States v. Andis","cite":"333 F.3d 886","y":2003,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/333/886/","by":{"0":"19","2":"15"}},{"t":"case","label":"United States v. Banks","cite":"776 F.3d 87","y":2015,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/776/87/","by":{"0":"18"}},{"t":"case","label":"United States v. Binkholder","cite":"832 F.3d 923","y":2016,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/832/923/","sum":"Stating that courts enforce an appeal waiver only if “a given appeal is clearly and unambiguously within [its] scope”.","sumSrc":"brief:0","by":{"0":"18"}},{"t":"case","label":"United States v. Brown","cite":"892 F.3d 385","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/892/385/","op":1,"sum":"Noting that “[l]ike all other courts of appeals,” the D.C. Circuit enforces a waiver only if it is “knowing, intelligent, and voluntary”.","sumSrc":"brief:0","by":{"0":"17"}},{"t":"case","label":"United States v. Burden","cite":"860 F.3d 45","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/860/45/","by":{"0":"32"}},{"t":"case","label":"United States v. Calderon","cite":"665 F. App’x 356","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/665/356/","sum":"Finding no duty to consult because “nothing material changed” after the defendant signed the appeal waiver.","sumSrc":"brief:0","by":{"0":"42"}},{"t":"case","label":"United States v. Chaney","cite":"581 F.3d 1123","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/581/1123/","by":{"0":"18"}},{"t":"case","label":"United States v. Cervantes","cite":"132 F.3d 1106","y":1998,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/132/1106/","by":{"0":"19"}},{"t":"case","label":"United States v. Cronic","cite":"466 U.S. 648","y":1984,"id":"1983/82-660","sc":1,"op":6,"sum":"The Court held that the Court of Appeals erred by inferring that the less-than-ideal circumstances leading up to the trial negatively influenced the lawyer’s performance. The Sixth Amendment protects the right for an accused to receive effective assistance of counsel in order to protect the adversary process.","sumSrc":"Oyez","by":{"0":"passim","1":"22, 31","2":"10, 12, 23"}},{"t":"case","label":"United States v. Dunlap","cite":"2010 WL 4614557","y":2010,"court":"W.D. Pa. Nov. 5","by":{"0":"37"}},{"t":"case","label":"United States v. Freeman","cite":"640 F.3d 180","y":2011,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/640/180/","by":{"0":"19"}},{"t":"case","label":"United States v. Goodson","cite":"544 F.3d 529","y":2008,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/544/529/","by":{"0":"18"}},{"t":"case","label":"United States v. Guillen","cite":"561 F.3d 527","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/561/527/","by":{"0":"19","2":"16, 18"}},{"t":"case","label":"United States v. Hahn","cite":"359 F.3d 1315","y":2004,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/359/1315/","by":{"0":"19, 38","2":"15"}},{"t":"case","label":"United States v. Hampton","cite":"732 F.3d 687","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/732/687/","by":{"0":"18"}},{"t":"case","label":"United States v. Hardman","cite":"778 F.3d 896","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/778/896/","op":1,"by":{"0":"17"}},{"t":"case","label":"United States v. Hunt","cite":"843 F.3d 1022","y":2016,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/843/1022/","by":{"0":"18, 31"}},{"t":"case","label":"United States v. Johnson","cite":"410 F.3d 137","y":2005,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/410/137/","by":{"0":"19"}},{"t":"case","label":"United States v. Johnson","cite":"541 F.3d 1064","y":2008,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/541/1064/","sum":"Interpreting a waiver to reach restitution challenges where it referred more generally to appeals of the defendant’s “sentence”.","sumSrc":"brief:0","by":{"0":"35","2":"17"}},{"t":"case","label":"United States v. Khattak","cite":"273 F.3d 557","y":2001,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/273/557/","by":{"0":"19","2":"17"}},{"t":"case","label":"United States v. Kieffer","cite":"794 F.3d 850","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/794/850/","by":{"0":"18"}},{"t":"case","label":"United States v. Lee","cite":"888 F.3d 503","y":2018,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/888/503/","sum":"Explaining that such a claim requires examination of “the entire record”.","sumSrc":"brief:0","by":{"0":"31","3":"15"}},{"t":"case","label":"United States v. Litos","cite":"847 F.3d 906","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/847/906/","by":{"0":"19"}},{"t":"case","label":"United States v. Lopez","cite":"655 F. Supp. 2d 720","y":2009,"court":"E.D. Ky.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/655/720/","op":2,"sum":"Noting that the defendant reserved the “right to appeal the District Court’s denial of his pretrial motions to suppress and the arguments contained therein”.","sumSrc":"brief:0","by":{"0":"34"}},{"t":"case","label":"United States v. Mabry","cite":"536 F.3d 231","y":2008,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/536/231/","op":1,"by":{"0":"37","1":"26"}},{"t":"case","label":"United States v. Maggio","cite":"862 F.3d 642","y":2017,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/862/642/","by":{"0":"18"}},{"t":"case","label":"United States v. May","cite":"855 F.3d 271","y":2017,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/855/271/","by":{"0":"18"}},{"t":"case","label":"United States v. Oladimeji","cite":"463 F.3d 152","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/463/152/","sum":"Interpreting a sentencing appeal waiver to preserve challenges to a restitution order based on the waiver’s reference to the “total term of imprisonment”.","sumSrc":"brief:0","by":{"0":"35"}},{"t":"case","label":"United States v. Orosco","cite":"219 F. App’x 673","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/219/673/","by":{"0":"41"}},{"t":"case","label":"United States v. Ortega-Hernandez","cite":"804 F.3d 447","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/804/447/","by":{"0":"18"}},{"t":"case","label":"United States v. Phillips","cite":"174 F.3d 1074","y":1999,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/174/1074/","by":{"0":"19"}},{"t":"case","label":"United States v. Puentes-Hurtado","cite":"794 F.3d 1278","y":2015,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/794/1278/","op":1,"sum":"Noting that “like the rest of [its] sister circuits,” the Eleventh Circuit holds that a claim that the government breached the plea agreement is not barred by an appeal waiver.","sumSrc":"brief:0","by":{"0":"18"}},{"t":"case","label":"United States v. Quiñones-Meléndez","cite":"791 F.3d 201","y":2015,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/791/201/","by":{"0":"18"}},{"t":"case","label":"United States v. Ready","cite":"82 F.3d 551","y":1996,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/82/551/","by":{"0":"17, 18"}},{"t":"case","label":"United States v. Riggi","cite":"649 F.3d 143","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/649/143/","by":{"0":"19","2":"15"}},{"t":"case","label":"United States v. Rosa","cite":"123 F.3d 94","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/123/94/","by":{"0":"18"}},{"t":"case","label":"United States v. Ruiz","cite":"536 U.S. 622","y":2002,"id":"2001/01-595","sc":1,"sum":"The Court held that the Constitution does not require the Government to disclose material impeachment evidence prior to entering a plea agreement with a criminal defendant.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"United States v. Story","cite":"439 F.3d 226","y":2006,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/439/226/","op":1,"by":{"0":"18"}},{"t":"case","label":"United States v. Tapp","cite":"491 F.3d 263","y":2007,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/491/263/","op":1,"sum":"Describing an appeal waiver that “reserved the right to appeal any punishment imposed in excess of the statutory maximum and any punishment that was an upward departure from the applicable guidelines range”.","sumSrc":"brief:0","by":{"0":"35"}},{"t":"case","label":"United States v. Teeter","cite":"257 F.3d 14","y":2001,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/257/14/","by":{"0":"19","2":"15"}},{"t":"case","label":"United States v. Valnor","cite":"451 F.3d 744","y":2006,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/451/744/","by":{"0":"18"}},{"t":"case","label":"United States v. Washington","cite":"588 F. App’x 586","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/588/586/","by":{"0":"41"}},{"t":"case","label":"United States v. White","cite":"584 F.3d 935","y":2009,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/584/935/","by":{"0":"18"}},{"t":"case","label":"United States v. Worden","cite":"646 F.3d 499","y":2011,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/646/499/","by":{"0":"35, 36"}},{"t":"case","label":"Watson v. United States","cite":"493 F.3d 960","y":2007,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/493/960/","op":1,"sum":"Recognizing the United States’ concession to the same effect.","sumSrc":"brief:3","by":{"0":"38","3":"21"}},{"t":"case","label":"Weaver v. Massachusetts","cite":"137 S. Ct. 1899","y":2017,"id":"2016/16-240","sc":1,"sum":"The Court determined that, in the context of the violation of a right to a public trial during jury selection, when the structural error was first raised via an ineffective assistance of counsel claim, the defendant must demonstrate that he suffered prejudice in order to secure a new trial.","sumSrc":"Oyez","by":{"0":"26","1":"32","2":"11"}},{"t":"case","label":"Weems v. United States","cite":"2018 WL 1470877","y":2018,"court":"W.D. Wash. Mar. 26","by":{"0":"41"}},{"t":"case","label":"Zanuccoli v. United States","cite":"459 F. Supp. 2d 109","y":2006,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/459/109/","sum":"Rejecting defendant’s claim that he instructed his counsel to appeal as “highly implausible,” without need for evidentiary hearing, given that “Petitioner expressly waived his right to appeal”.","sumSrc":"brief:0","by":{"0":"40"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"0":"passim","1":"12","2":"7, 11, 22"}},{"t":"usc","label":"28 U.S.C. § 1257","url":"https://www.law.cornell.edu/uscode/text/28/1257","by":{"0":"3"}},{"t":"rule","label":"Fed. R. App. P. 11","url":"https://www.law.cornell.edu/rules/frap/rule_11","subs":["(g)"],"by":{"0":"38"}},{"t":"rule","label":"Fed. R. App. P. 27","url":"https://www.law.cornell.edu/rules/frap/rule_27","by":{"0":"39"}},{"t":"case","label":"Bell v. Cone","cite":"535 U.S. 685","y":2002,"id":"2001/01-400","sc":1,"sum":"The Court held that Tennessee Court of Criminal Appeals's decision neither was \"contrary to\" nor involved \"an unreasonable application of clearly established Federal law\" under the provisions of 28 USC section 2254(d)(1).","sumSrc":"Oyez","by":{"1":"31","2":"12","3":"10"}},{"t":"case","label":"Boykin v. Alabama","cite":"395 U.S. 238","y":1969,"id":"1968/642","sc":1,"op":2,"sum":"The Court held that a guilty plea is a confession, and the admissibility of a confession is contingent on the confirmation that it was made voluntarily. The waiver of several constitutional rights is involved in a guilty plea. A defendant’s silence is insufficient to show that he understood these rights and chose to waive them.","sumSrc":"Oyez","by":{"1":"10","3":"9"}},{"t":"case","label":"Charboneau v. State","cite":"102 P.3d 1108","y":2004,"court":"Idaho","url":"https://www.courtlistener.com/c/P.3d/102/1108/","by":{"1":"29, 34"}},{"t":"case","label":"Glover v. United States","cite":"531 U.S. 198","y":2001,"id":"2000/99-8576","sc":1,"sum":"The Court held that Court of appeals erred in engrafting onto the prejudice branch of the Strickland test the requirement that any increase in sentence must meet a standard of significance. Thus, the denial of Glover's motion to correct his sentence was reversed and remanded.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Harrington v. Richter","cite":"562 U.S. 86","y":2011,"id":"2010/09-587","sc":1,"sum":"The Court held that a defense lawyer was not deficient for failing to consult blood evidence when planning strategy for trial.","sumSrc":"Oyez","by":{"1":"12, 18"}},{"t":"case","label":"Hill v. Lockhart","cite":"474 U.S. 52","y":1985,"id":"1985/84-1103","sc":1,"sum":"The District Court did not err in declining to hold a hearing on petitioner's claim.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30, 33"}},{"t":"case","label":"Kimmelman v. Morrison","cite":"477 U.S. 365","y":1986,"id":"1985/84-1661","sc":1,"sum":"At respondent's bench trial in a New Jersey court resulting in his conviction of rape, a police officer testified that a few hours after the rape she accompanied the victim to respondent's apartment where the rape had occurred; that he was not there but another tenant let them into respondent's apartment; and that the officer seized a sheet from respondent's bed. At such point in the testimony, respondent's counsel …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"31, 33"}},{"t":"case","label":"Lockhart v. Fretwell","cite":"506 U.S. 364","y":1993,"id":"1992/91-1393","sc":1,"sum":"Counsel's failure to make the Collins objection during the sentencing proceeding did not constitute prejudice within the meaning of Strickland v. Washington, supra. To show prejudice under Strickland, a defendant must demonstrate that counsel's errors are so serious as to deprive him of a trial whose result is unfair or unreliable, id., at 687, not merely that the outcome would have been different. Unfairness or …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"22"}},{"t":"case","label":"Martinez v. Ryan","cite":"566 U.S. 1","y":2012,"id":"2011/10-1001","sc":1,"sum":"The Court held that a defendant who is prohibited by state law from raising a claim of ineffective assistance of counsel may establish cause for such a claim at trial by showing evidence of ineffective assistance up to that point.","sumSrc":"Oyez","by":{"1":"34"}},{"t":"case","label":"Massaro v. United States","cite":"538 U.S. 500","y":2003,"id":"2002/01-1559","sc":1,"op":1,"sum":"The Court held that failure to raise an ineffective-assistance-of-counsel claim on direct appeal does not bar the claim from being brought in a collateral proceeding under section 2255, whether or not the petitioner could have raised the claim on direct appeal.","sumSrc":"Oyez","by":{"1":"34","2":"24"}},{"t":"case","label":"McKinney v. State","cite":"396 P.3d 1168","y":2017,"court":"Idaho","url":"https://www.courtlistener.com/c/P.3d/396/1168/","by":{"1":"18, 19, 25, 26"}},{"t":"case","label":"Missouri v. Frye","cite":"566 U.S. 134","y":2012,"id":"2011/10-444","sc":1,"sum":"The Court held that the Sixth Amendment requires defense attorneys to communicate formal plea offers from the prosecution.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Padilla v. Kentucky","cite":"559 U.S. 356","y":2010,"id":"2009/08-651","sc":1,"op":1,"sum":"The Court held that counsel must inform a client whether or not his plea carries a risk of deportation under the Sixth Amendment.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 362","y":2000,"id":"1999/98-8384","sc":1,"op":1,"sum":"In a judgment announced by Justice John Paul Stevens, the Court, with different majorities of Justices for each holding, held that Williams had been deprived of the constitutional right to the effective assistance of counsel and that the Virginia Supreme Court's refusal to set aside the Williams death sentence was a decision that was contrary to or involved an unreasonable application of clearly established federal law, as determined by the Court.","sumSrc":"Oyez","by":{"1":"12","2":"12, 24"}},{"t":"case","label":"Wong v. Belmontes","cite":"558 U.S. 15","y":2009,"id":"2009/08-1263","sc":1,"sum":"The Court held that a death row inmate's attorney did not undermine his conviction.","sumSrc":"Oyez","by":{"1":"12"}},{"t":"case","label":"Wright v. Van Patten","cite":"552 U.S. 120","y":2008,"id":"2007/07-212","sc":1,"sum":"Unfortunately for Van Patten, the Court felt that there was no concrete prohibition of representation by speakerphone in the federal case law and therefore determined that \"no clearly established law contrary to the state court's conclusion justifies collateral relief.\" Therefore, the Court reversed the Seventh Circuit's decision granting Van Patten relief and remanded the case to the lower courts for further proceedings.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"Wright v. West","cite":"505 U.S. 277","y":1992,"id":"1991/91-542","sc":1,"sum":"The judgment is reversed, and the case is remanded. 931 F. 2d 262, reversed and remanded. JUSTICE THOMAS, joined by THE CMHEF JUSTICE and JUSTICE ScALiA, concluded that regardless of whether a federal habeas court should review state-court applications of law to fact deferentially or de novo, the trial record contains more than enough evidence to support West's conviction. Jackson repeatedly emphasizes the deference …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"12"}},{"t":"case","label":"(III) Cases—Continued: Berrio-Callejas v. United States","cite":"129 F.3d 1252","y":1997,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/129/1252/","by":{"2":"30"}},{"t":"case","label":"Blackledge v. Allison","cite":"431 U.S. 63","y":1977,"id":"1976/75-1693","sc":1,"sum":"In light of the nature of the record of the proceeding at which the guilty plea was accepted, and of the ambiguous status of the process of plea bargaining at the time the guilty plea was made, respondent's petition for a writ of habeas corpus should not have been summarily dismissed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"31"}},{"t":"case","label":"Bordenkircher v. Hayes","cite":"434 U.S. 357","y":1978,"id":"1977/76-1334","sc":1,"sum":"The Court held that the defendant's due process rights were not violated in this case. Justice Stewart spent some time describing the important role that plea bargaining plays in the nation's legal system, a role that has been accepted by the Supreme Court in cases such as Blackledge v. Allison (1977) and Brady v. United States (1970).","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Brady v. United States","cite":"397 U.S. 742","y":1970,"id":"1969/270","sc":1,"op":1,"sum":"The Supreme Court held that United States v. Jackson does not require every guilty plea to be overturned when fear of death was a factor in the plea. The voluntariness of the plea is determined by considering all of the relevant circumstances. While Brady may have been partially motivated by a desire to avoid the death penalty, the guilty plea was voluntarily made with the advice of competent counsel.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Chambers v. Maroney","cite":"399 U.S. 42","y":1970,"id":"1969/830","sc":1,"sum":"Petitioner was one of four men arrested after the auto in which they were riding was stopped by police shortly after an armed robbery of a service station. The arrests resulted from information supplied by the service station attendant and bystanders. The car was driven to a police station, where a search disclosed two revolvers, one loaded with dumdum bullets, and cards bearing the name of an attendant at another …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"Martin v. United States","cite":"2012 WL 2061934","y":2012,"court":"D. Me. June 7","by":{"2":"30"}},{"t":"case","label":"Ricketts v. Adamson","cite":"483 U.S. 1","y":1987,"id":"1986/86-6","sc":1,"sum":"Respondent's prosecution for first-degree murder did not violate double jeopardy principles, since his breach of the plea agreement removed the double jeopardy bar that otherwise would prevail, assuming that under state law second-degree murder is a lesser included offense of first-degree murder.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15, 18"}},{"t":"case","label":"Rodriguez v. United States","cite":"741 F. Supp. 2d 344","y":2010,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/741/344/","by":{"2":"30"}},{"t":"case","label":"Town of Newton v. Rumery","cite":"480 U.S. 386","y":1987,"id":"1986/85-1449","sc":1,"sum":"The judgment is reversed, and the case is remanded. 778 F. 2d 66, reversed and remanded. JUSTICE POWELL delivered the opinion of the Court with respect to Parts I, II, III-A, IV, and V, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15"}},{"t":"case","label":"Underwood v. United States","cite":"2016 WL 554835","y":2016,"court":"E.D. Tenn. Feb. 10","by":{"2":"30"}},{"t":"case","label":"United States v. Andrade-Martinez","cite":"536 Fed. Appx. 385","y":2013,"court":"4th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./536/385/","by":{"2":"29"}},{"t":"case","label":"United States v. Bascomb","cite":"451 F.3d 1292","y":2006,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/451/1292/","by":{"2":"15"}},{"t":"case","label":"United States v. Beals","cite":"698 F.3d 248","y":2012,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/698/248/","by":{"2":"15"}},{"t":"case","label":"United States v. Bond","cite":"414 F.3d 542","y":2005,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/414/542/","by":{"2":"17"}},{"t":"case","label":"United States v. Broce","cite":"488 U.S. 563","y":1989,"id":"1988/87-1190","sc":1,"sum":"Respondents' double jeopardy challenge is foreclosed by their guilty pleas and convictions.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"United States v. Cardenas","cite":"405 F.3d 1046","court":"9th Cir. 15","url":"https://www.courtlistener.com/c/F.3d/405/1046/","by":{"2":"15"}},{"t":"case","label":"United States v. Chandler","cite":"534 F.3d 45","y":2008,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/534/45/","by":{"2":"17"}},{"t":"case","label":"United States v. Chapa","cite":"602 F.3d 865","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/602/865/","by":{"2":"17"}},{"t":"case","label":"United States v. Cohen","cite":"459 F.3d 490","y":2006,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/459/490/","by":{"2":"17"}},{"t":"case","label":"United States v. Gonzalez-Lopez","cite":"548 U.S. 140","y":2006,"id":"2005/05-352","sc":1,"op":1,"sum":"In a 5-to-4 decision authored by Justice Antonin Scalia, the Supreme Court held that a denial of the Sixth Amendment right to paid counsel of one's own choosing is \"structural\" error.","sumSrc":"Oyez","by":{"2":"11, 12, 19, 22"}},{"t":"case","label":"United States v. Leyva-Matos","cite":"618 F.3d 1213","y":2010,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/618/1213/","by":{"2":"17"}},{"t":"case","label":"United States v. Lockwood","cite":"416 F.3d 604","y":2005,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/416/604/","by":{"2":"15"}},{"t":"case","label":"United States v. Lopez-Armenta","cite":"400 F.3d 1173","y":2005,"url":"https://www.courtlistener.com/c/F.3d/400/1173/","by":{"2":"17"}},{"t":"case","label":"United States v. Manning","cite":"755 F.3d 455","y":2014,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/755/455/","by":{"2":"29"}},{"t":"case","label":"United States v. Marin","cite":"961 F.2d 493","y":1992,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/961/493/","by":{"2":"15"}},{"t":"case","label":"United States v. Mezzanatto","cite":"513 U.S. 196","y":1995,"id":"1994/93-1340","sc":1,"sum":"An agreement to waive the plea-statement Rules' exclusionary provisions is valid and enforceable absent some affirmative indication that the defendant entered the agreement unknowingly or involuntarily.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15"}},{"t":"case","label":"United States v. Monahan","cite":"405 Fed. Appx. 742","y":2010,"court":"4th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./405/742/","by":{"2":"29"}},{"t":"case","label":"United States v. Poindexter","cite":"492 F.3d 263","y":2007,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/492/263/","op":1,"by":{"2":"28"}},{"t":"case","label":"United States v. Rene","cite":"577 Fed. Appx. 316","url":"https://www.courtlistener.com/c/Fed.%20Appx./577/316/","by":{"2":"15"}},{"t":"case","label":"United States v. Richardson","cite":"558 F.3d 680","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/558/680/","by":{"2":"18"}},{"t":"case","label":"United States v. Rodriguez","cite":"416 F.3d 123","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/416/123/","by":{"2":"17"}},{"t":"case","label":"United States v. Rutan","cite":"956 F.2d 827","y":1992,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/956/827/","by":{"2":"16, 17"}},{"t":"case","label":"United States v. Sharp","cite":"442 F.3d 946","y":2006,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/442/946/","by":{"2":"17"}},{"t":"case","label":"United States v. Washington","cite":"515 F.3d 861","y":2008,"url":"https://www.courtlistener.com/c/F.3d/515/861/","by":{"2":"17"}},{"t":"case","label":"United States v. Wilson","cite":"429 F.3d 455","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/429/455/","by":{"2":"15"}},{"t":"case","label":"United States v. Whitlow","cite":"287 F.3d 638","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/287/638/","by":{"2":"20"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)(1)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§922. Unlawful acts","tname":"Crimes and Criminal Procedure","by":{"2":"2"}},{"t":"usc","label":"18 U.S.C. § 3742","url":"https://www.law.cornell.edu/uscode/text/18/3742","subs":["(a)"],"stext":{"head":"§3742. Review of a sentence","paras":[[0,"(a) Appeal by a Defendant.—A defendant may file a notice of appeal in the district court for review of an otherwise final sentence if the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines; or"],[1,"(3) is greater than the sentence specified in the applicable guideline range to the extent that the sentence includes a greater fine or term of imprisonment, probation, or supervised release than the maximum established in the guideline range, or includes a more limiting condition of probation or supervised release under section 3563(b)(6) or (b)(11) 1 than the maximum established in the guideline range; or"],[1,"(4) was imposed for an offense for which there is no sentencing guideline and is plainly unreasonable."],[0,"(b) Appeal by the Government.—The Government may file a notice of appeal in the district court for review of an otherwise final sentence if the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines;"],[1,"(3) is less than the sentence specified in the applicable guideline range to the extent that the sentence includes a lesser fine or term of imprisonment, probation, or supervised release than the minimum established in the guideline range, or includes a less limiting condition of probation or supervised release under section 3563(b)(6) or (b)(11) 1 than the minimum established in the guideline range; or"],[1,"(4) was imposed for an offense for which there is no sentencing guideline and is plainly unreasonable."],[0,"The Government may not further prosecute such appeal without the personal approval of the Attorney General, the Solicitor General, or a deputy solicitor general designated by the Solicitor General."],[0,"(c) Plea Agreements.—In the case of a plea agreement that includes a specific sentence under rule 11(e)(1)(C) of the Federal Rules of Criminal Procedure—"],[1,"(1) a defendant may not file a notice of appeal under paragraph (3) or (4) of subsection (a) unless the sentence imposed is greater than the sentence set forth in such agreement; and"],[1,"(2) the Government may not file a notice of appeal under paragraph (3) or (4) of subsection (b) unless the sentence imposed is less than the sentence set forth in such agreement."],[0,"(d) Record on Review.—If a notice of appeal is filed in the district court pursuant to subsection (a) or (b), the clerk shall certify to the court of appeals—"],[1,"(1) that portion of the record in the case that is designated as pertinent by either of the parties;"],[1,"(2) the presentence report; and"],[1,"(3) the information submitted during the sentencing proceeding."],[0,"(e) Consideration.—Upon review of the record, the court of appeals shall determine whether the sentence—"],[1,"(1) was imposed in violation of law;"],[1,"(2) was imposed as a result of an incorrect application of the sentencing guidelines;"],[1,"(3) is outside the applicable guideline range, and"],[2,"(A) the district court failed to provide the written statement of reasons required by section 3553(c);"],[2,"(B) the sentence departs from the applicable guideline range based on a factor that—"],[3,"(i) does not advance the objectives set forth in section 3553(a)(2); or"],[3,"(ii) is not authorized under section 3553(b); or"],[3,"(iii) is not justified by the facts of the case; or"],[2,"(C) the sentence departs to an unreasonable degree from the applicable guidelines range, having regard for the factors to be considered in imposing a sentence, as set forth in section 3553(a) of this title and the reasons for the imposition of the particular sentence, as stated by the district court pursuant to the provisions of section 3553(c); or"],[1,"(4) was imposed for an offense for which there is no applicable sentencing guideline and is plainly unreasonable."],[0,"The court of appeals shall give due regard to the opportunity of the district court to judge the credibility of the witnesses, and shall accept the findings of fact of the district court unless they are clearly erroneous and, except with respect to determinations under subsection (3)(A) or (3)(B), shall give due deference to the district court's application of the guidelines to the facts. With respect to determinations under subsection (3)(A) or (3)(B), the court of appeals shall review de novo the district court's application of the guidelines to the facts."],[0,"(f) Decision and Disposition.—If the court of appeals determines that—"],[1,"(1) the sentence was imposed in violation of law or imposed as a result of an incorrect application of the sentencing guidelines, the court shall remand the case for further sentencing proceedings with such instructions as the court considers appropriate;"],[1,"(2) the sentence is outside the applicable guideline range and the district court failed to provide the required statement of reasons in the order of judgment and commitment, or the departure is based on an impermissible factor, or is to an unreasonable degree, or the sentence was imposed for an offense for which there is no applicable sentencing guideline and is plainly unreasonable, it shall state specific reasons for its conclusions and—"],[2,"(A) if it determines that the sentence is too high and the appeal has been filed under subsection (a), it shall set aside the sentence and remand the case for further sentencing proceedings with such instructions as the court considers appropriate, subject to subsection (g);"],[2,"(B) if it determines that the sentence is too low and the appeal has been filed under subsection (b), it shall set aside the sentence and remand the case for further sentencing proceedings with such instructions as the court considers appropriate, subject to subsection (g);"],[1,"(3) the sentence is not described in paragraph (1) or (2), it shall affirm the sentence."],[0,"(g) Sentencing Upon Remand.—A district court to which a case is remanded pursuant to subsection (f)(1) or (f)(2) shall resentence a defendant in accordance with section 3553 and with such instructions as may have been given by the court of appeals, except that—"],[1,"(1) In determining the range referred to in subsection 3553(a)(4), the court shall apply the guidelines issued by the Sentencing Commission pursuant to section 994(a)(1) of title 28, United States Code, and that were in effect on the date of the previous sentencing of the defendant prior to the appeal, together with any amendments thereto by any act of Congress that was in effect on such date; and"],[1,"(2) The court shall not impose a sentence outside the applicable guidelines range except upon a ground that—"],[2,"(A) was specifically and affirmatively included in the written statement of reasons required by section 3553(c) in connection with the previous sentencing of the defendant prior to the appeal; and"],[2,"(B) was held by the court of appeals, in remanding the case, to be a permissible ground of departure."],[0,"(h) Application to a Sentence by a Magistrate Judge.—An appeal of an otherwise final sentence imposed by a United States magistrate judge may be taken to a judge of the district court, and this section shall apply (except for the requirement of approval by the Attorney General or the Solicitor General in the case of a Government appeal) as though the appeal were to a court of appeals from a sentence imposed by a district court."],[0,"(i) Guideline Not Expressed as a Range.—For the purpose of this section, the term \"guideline range\" includes a guideline range having the same upper and lower limits."],[0,"(j) Definitions.—For purposes of this section—"],[1,"(1) a factor is a \"permissible\" ground of departure if it—"],[2,"(A) advances the objectives set forth in section 3553(a)(2); and"],[2,"(B) is authorized under section 3553(b); and"],[2,"(C) is justified by the facts of the case; and"],[1,"(2) a factor is an \"impermissible\" ground of departure if it is not a permissible factor within the meaning of subsection (j)(1)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3742?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3742. Review of a sentence","tname":"Crimes and Criminal Procedure","by":{"2":"15"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","stext":{"head":"§1291. Final decisions of district courts","paras":[[0,"The courts of appeals (other than the United States Court of Appeals for the Federal Circuit) shall have jurisdiction of appeals from all final decisions of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, except where a direct review may be had in the Supreme Court. The jurisdiction of the United States Court of Appeals for the Federal Circuit shall be limited to the jurisdiction described in sections 1292(c) and (d) and 1295 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1291?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1291. Final decisions of district courts","tname":"Judiciary and Judicial Procedure","by":{"2":"15"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"2":"15"}},{"t":"case","label":"Bousley v. United States","cite":"523 U.S. 614","y":1998,"id":"1997/96-8516","sc":1,"ar":1,"sum":"The Court held that, although Bousley's claim was procedurally defaulted, Bousley may be entitled to a hearing on the merits of it if he makes the necessary showing to relieve the default.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"Nunez v. United States","cite":"554 U.S. 911","y":2008,"url":"https://supreme.justia.com/cases/federal/us/554/911/","sc":1,"by":{"3":"20"}},{"t":"case","label":"Rose v. Lundy","cite":"455 U.S. 509","y":1982,"id":"1981/80-846","sc":1,"sum":"The judgment is reversed and the case is remanded. 624 F. 2d 1100, reversed and remanded. JUSTICE O'CONNOR delivered the opinion of the Court with respect to Parts I, II, III-A, III-B, and IV, concluding that a district court must dismiss habeas petitions containing both unexhausted and exhausted claims. A rule requiring exhaustion of all claims in state courts promotes comity and furthers the purposes underlying …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"17"}},{"t":"case","label":"State v. Peterson","cite":"226 P.3d 535","y":2010,"court":"Idaho","url":"https://www.courtlistener.com/c/P.3d/226/535/","sum":"Recognizing that plea agreements are construed strictly in favor of the defendant.","sumSrc":"brief:3","by":{"3":"15"}},{"t":"case","label":"United States v. Capaldi","cite":"134 F.3d 307","y":1998,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/134/307/","sum":"Recognizing that plea agreements are construed strictly in favor of the defendant.","sumSrc":"brief:3","by":{"3":"15"}},{"t":"case","label":"United States v. Medina-Carrasco","cite":"815 F.3d 457","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/815/457/","by":{"3":"16"}},{"t":"rule","label":"Fed. R. Crim. P. 11","url":"https://www.law.cornell.edu/rules/frcrmp/rule_11","subs":["(b)(1)(A)"],"by":{"3":"9"}}]};